const fs = require\('fs'\);
const raw = fs.readFileSync\('ktuluekit-migration.json', 'utf8'\);
const data = JSON.parse\(raw\); // throws if invalid JSON

const apps = data.apps;
const allItems = [];
for \(const app of apps\) {
  for \(const item of app.items\) {
    allItems.push\({ id: app.name + ':' + item.label, app: app.name, label: item.label, category: app.category, item }\);
  }
}

console.log\('=== ALL APP ITEMS ==='\);
allItems.forEach\(\(x, i\) => console.log\(\(i+1\).toString\(\).padStart\(2\) + '. [' + x.category + '] ' + x.id\)\);
console.log\('\\nTotal app items:', allItems.length\);

const fullRestore = data.profiles.find\(p => p.name === 'Full Restore'\);
console.log\('\\n=== FULL RESTORE PROFILE ==='\);
console.log\('Count:', fullRestore.ids.length\);
const allIds = new Set\(allItems.map\(x => x.id\)\);
const frIds = new Set\(fullRestore.ids\);
const missingFromFR = [...allIds].filter\(x => !frIds.has\(x\)\);
const extraInFR = [...frIds].filter\(x => !allIds.has\(x\)\);
console.log\('Missing from Full Restore:', missingFromFR\);
console.log\('Extra in Full Restore \(not in apps\):', extraInFR\);

const devTools = data.profiles.find\(p => p.name === 'Dev Tools'\);
console.log\('\\n=== DEV TOOLS PROFILE ==='\);
console.log\('Count:', devTools.ids.length\);
console.log\('IDs:', devTools.ids\);

// Check strategies
const personalFiles = apps.find\(a => a.name === 'Personal Files'\);
console.log\('\\n=== PERSONAL FILES STRATEGIES ==='\);
for \(const item of personalFiles.items\) {
  console.log\(item.label + ': strategy=' + item.strategy\);
}

// Check categories
const categories = {};
for \(const app of apps\) {
  if \(!categories[app.category]\) categories[app.category] = [];
  categories[app.category].push\(app.name\);
}
console.log\('\\n=== CATEGORIES ==='\);
for \(const [cat, names] of Object.entries\(categories\)\) {
  console.log\(cat + ': ' + names.join\(', '\)\);
}

console.log\('\\nJSON is VALID \(no parse errors\)'\);
")
